def solve(xs: list[int]) -> int:
    n = len(xs)
    if n == 0:
        return 0
    total = 0
    for i, x in enumerate(xs):
        weight = ((i + 1) % n) + 1
        total += x * weight
    return total % 97

def solve(xs: list[int]) -> int:
    level = 0
    deepest = 0
    for x in xs:
        if x > 0:
            level += 1
            if level > deepest:
                deepest = level
        else:
            level -= 1
            if level < 0:
                return 0
    if level != 0:
        return 0
    return deepest

